.caps-surface.--caps-surface-molding-base:
color-mix(
      in oklab,
      var(--color-base-100),
      var(--color-base-200) calc(var(--depth) * 100%)
    )

.caps-surface.--caps-surface-molding:
linear-gradient(
      155deg,
      color-mix(
        in oklab,
        var(--caps-surface-molding-base),
        var(--color-base-content)
          calc(var(--depth) * var(--stipe-surface-molding-contrast))
      ),
      var(--caps-surface-molding-base) 50%,
      color-mix(
        in oklab,
        var(--caps-surface-molding-base),
        white calc(var(--depth) * var(--stipe-surface-molding-contrast))
      )
    )

.caps-surface.border:
var(--caps-surface-rim) solid
      color-mix(
        in oklab,
        transparent,
        var(--stipe-linework) calc((1 - var(--depth)) * 100%)
      )

.caps-surface.background:
linear-gradient(
          var(--caps-surface-face, var(--color-base-100)),
          var(--caps-surface-face, var(--color-base-100))
        )
        padding-box,
      var(--stipe-surface-frame-image, var(--caps-surface-molding)) border-box

.caps-surface.boxShadow:
var(
      --stipe-shadow-raised,
      0 0 0 calc(var(--depth) * 1px)
        color-mix(
          in oklab,
          var(--color-base-content) 12%,
          var(--color-base-200)
        ),
      0 0 0 calc(var(--depth) * 3px) var(--color-base-200),
      0 calc(var(--depth) * 1px) 0 calc(var(--depth) * 4px)
        oklch(100% 0 0 / calc(var(--depth) * 0.3))
    )

.caps-display-gasket.boxShadow:
var(
      --stipe-shadow-inset,
      inset 0 calc(var(--depth) * 1px) calc(var(--depth) * 2px)
        color-mix(
          in oklab,
          var(--color-base-content) calc(var(--depth) * 20%),
          transparent
        )
    )

.caps-screen.boxShadow:
var(
      --stipe-shadow-inset,
      inset 0 calc(var(--depth) * 1px) calc(var(--depth) * 2px)
        color-mix(
          in oklab,
          var(--color-base-content) calc(var(--depth) * 12%),
          transparent
        )
    )

.caps-window.boxShadow:
var(
      --caps-window-shadow,
      var(
        --stipe-shadow-raised,
        0 calc(var(--depth) * 2px) calc(var(--depth) * 6px)
          color-mix(
            in srgb,
            var(--color-base-content) calc(var(--depth) * 4%),
            transparent
          )
      )
    )

.caps-window[data-active=\"true\"].boxShadow:
var(
      --caps-window-shadow,
      var(
        --stipe-shadow-raised,
        0 0 0 calc(var(--depth) * 1px)
          color-mix(
            in srgb,
            var(--color-primary) calc(var(--depth) * 10%),
            transparent
          ),
        0 calc(var(--depth) * 4px) calc(var(--depth) * 12px)
          color-mix(
            in srgb,
            var(--color-base-content) calc(var(--depth) * 6%),
            transparent
          )
      )
    )

.caps-window[data-active=\"true\"] .caps.background:
color-mix(
      in oklab,
      var(--color-primary)
        var(
          --caps-window-header-active-tint,
          var(--caps-window-header-tint, 0%)
        ),
      var(--caps-window-header-face, var(--color-base-200))
    )

.caps-window[data-floating=\"true\"].boxShadow:
var(
      --caps-window-shadow,
      var(
        --stipe-shadow-raised,
        0 calc(var(--depth) * 2px) calc(var(--depth) * 4px)
          color-mix(
            in srgb,
            var(--color-base-300) calc(var(--depth) * 30%),
            transparent
          ),
        0 calc(var(--depth) * 12px) calc(var(--depth) * 28px)
          calc(var(--depth) * -8px)
          color-mix(
            in srgb,
            var(--color-base-300) calc(var(--depth) * 55%),
            transparent
          )
      )
    )

.caps-window-header.background:
color-mix(
      in oklab,
      var(--color-primary) var(--caps-window-header-tint, 0%),
      var(--caps-window-header-face, var(--color-base-200))
    )

.caps-window-snap-preview.boxShadow:
var(
      --stipe-shadow-raised,
      inset 0 calc(var(--depth) * 1px) 0
        color-mix(in oklab, white calc(var(--depth) * 40%), transparent),
      inset 0 calc(var(--depth) * -2px) 0
        color-mix(
          in oklab,
          var(--color-info) calc(var(--depth) * 25%),
          transparent
        )
    )

.caps-button-filled.--caps-button-filled-edge:
var(
      --caps-button-border-color,
      color-mix(
        in oklab,
        color-mix(in oklab, var(--btn-bg), black calc(var(--depth) * 8%)),
        var(--stipe-linework)
          calc((1 - var(--depth)) * var(--caps-button-linework, 100%))
      )
    )

.caps-number-field-input.caps-input.--caps-input-floor:
var(
      --caps-control-number-face,
      color-mix(
        in oklab,
        var(--color-base-200) calc(100% - var(--depth) * 4%),
        var(--color-base-content) calc(var(--depth) * 4%)
      )
    )

.caps-number-field-input.caps-input.borderColor:
var(
      --caps-control-number-line,
