        0 0 / 100% 100% no-repeat,
      repeating-linear-gradient(
          to right,
          var(--caps-spec-tick) 0 1px,
          transparent 1px 8px
        )
        0 100% / 100% 7px no-repeat,
      var(--color-base-100)

.caps-pricing-card-banded.boxShadow:
var(
      --caps-pricing-shadow,
      calc(var(--caps-pricing-card-offset) * 1.5)
        calc(var(--caps-pricing-card-offset) * 1.5) 0
        color-mix(in oklab, var(--color-base-content) 30%, transparent)
    )

.caps-upload-row.border:
var(--border) solid
